-- New KineAid exercise: hollow hold (abdominals; legs and shoulders off the floor, held 30 s), with 3D puppet.
-- Safe to run more than once.

insert into public.exercises (source, source_id, source_url, license, author, kind, per_side, body_parts, muscles, equipment, level, default_sets, default_reps, default_hold_sec, default_rest_sec, owner_id, puppet, updated_at)
values ('kineaid', 'hollow-hold', '', 'KineAid', 'KineAid', 'time', false, array['core']::text[], array['abdominals', 'rectus abdominis', 'hip flexors']::text[], 'body only', 'intermediate', 3, 1, 30, 45, null, '{"base":"supine","keyframes":[{"pose":{},"move":1.2,"hold":1},{"pose":{"pelvis":[-100,0,0],"chest":[40,0,0],"neck":[20,0,0],"l_hip":[-5,0,2],"r_hip":[-5,0,-2],"l_knee":[0,0,0],"r_knee":[0,0,0],"l_ankle":[20,0,0],"r_ankle":[20,0,0],"l_shoulder":[-25,0,8],"r_shoulder":[-25,0,-8],"l_elbow":[0,0,0],"r_elbow":[0,0,0]},"move":1.5,"hold":3}],"props":[{"type":"mat"}],"view":{"az":90,"el":12},"highlight":["abdomen"]}'::jsonb, now())
on conflict (source, source_id) do update set kind = excluded.kind, per_side = excluded.per_side, body_parts = excluded.body_parts, muscles = excluded.muscles,
  equipment = excluded.equipment, level = excluded.level, default_sets = excluded.default_sets, default_reps = excluded.default_reps,
  default_hold_sec = excluded.default_hold_sec, default_rest_sec = excluded.default_rest_sec, puppet = excluded.puppet, updated_at = now();
insert into public.exercise_translations (exercise_id, locale, name, description, instructions, attention_points)
select id, 'nl', 'Holle houding (hollow hold)', 'Versterkt vooral de buikspieren door benen en bovenlichaam los van de grond te houden.', array['Lig op je rug op een mat, benen gestrekt, armen naast je lichaam.', 'Duw je onderrug plat tegen de mat door je buik aan te spannen.', 'Til je hoofd en schouders op en strek je armen naar je voeten.', 'Til tegelijk je gestrekte benen een eind van de grond.', 'Houd deze positie aan en leg daarna rustig alles terug neer.']::text[], array['Je onderrug blijft de hele tijd tegen de mat; komt ze los, til je benen dan hoger of buig je knieën.', 'Kin licht naar de borst, niet aan je nek trekken.', 'Blijf rustig doorademen.']::text[] from public.exercises where source = 'kineaid' and source_id = 'hollow-hold'
on conflict (exercise_id, locale) do update set name = excluded.name, description = excluded.description, instructions = excluded.instructions, attention_points = excluded.attention_points;
insert into public.exercise_translations (exercise_id, locale, name, description, instructions, attention_points)
select id, 'en', 'Hollow hold', 'Strengthens mainly the abdominal muscles by keeping the legs and upper body off the floor.', array['Lie on your back on a mat, legs straight, arms by your sides.', 'Press your lower back flat into the mat by tightening your abdominal muscles.', 'Lift your head and shoulders and reach your arms towards your feet.', 'At the same time, lift your straight legs a little off the floor.', 'Hold this position, then slowly lower everything again.']::text[], array['Your lower back stays on the mat the whole time; if it lifts, raise your legs higher or bend your knees.', 'Chin slightly towards your chest; do not pull on your neck.', 'Keep breathing calmly.']::text[] from public.exercises where source = 'kineaid' and source_id = 'hollow-hold'
on conflict (exercise_id, locale) do update set name = excluded.name, description = excluded.description, instructions = excluded.instructions, attention_points = excluded.attention_points;
